#!/usr/bin/env python3
"""Author-disclosed, metadata-only review of an already completed Slots run2.
Never executes a compiler, guard, checker, dependency build or version query.
Requires the root-reported terminal verification SHA; writes no PASS until every check closes.
"""
from pathlib import Path
import argparse,hashlib,json,re,os
B=Path('/tmp/zfc-validator-native-gic-slots')
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
load=lambda p:json.loads(Path(p).read_text())
desc=lambda p:dict(path=str(Path(p).resolve()),sha256=sha(p))
p=argparse.ArgumentParser();p.add_argument('--verification-sha',required=True);args=p.parse_args()
checks=0;tracked={}
def need(v,msg):
 global checks
 checks+=1
 if not v:raise AssertionError(msg)
def pin(path,h):
 path=Path(path).resolve();need(str(path) not in tracked or tracked[str(path)]==h,'conflicting input '+str(path))
 need(path.is_file() and sha(path)==h,'changed input '+str(path));tracked[str(path)]=h;return path
def reports(t):
 return [dict(name=n,axioms=sorted({v.strip() for v in a.split(',') if v.strip()})) for n,a in re.findall(r"^'([^\n]+)'[ \t]+(?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",t,re.M)]
def imports(path):return re.findall(r'^import\s+([A-Za-z_][A-Za-z_0-9.]*)\s*$',Path(path).read_text(),re.M)
def first(rec,m):
 roots=[Path(x) for x in rec['LEAN_PATH'].split(os.pathsep)]+[Path(rec['compiler']['path']).parent.parent/'lib/lean']
 rel=Path(m.replace('.','/')).with_suffix('.olean')
